"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq
import sys

Cell = tuple[int, int]  # (row, col)

TILE_ENTRY_COST: dict[str, int] = {
    ".": 1,
    "D": 3,
    "S": 1,
    "G": 1,
}


def _locate_symbol(grid: list[str], target_symbol: str) -> Cell | None:
    for row_idx, row_text in enumerate(grid):
        col_idx = row_text.find(target_symbol)
        if col_idx != -1:
            return (row_idx, col_idx)
    return None


def _neighbors_with_cost(grid: list[str], cell: Cell) -> list[tuple[Cell, int]]:
    row_idx, col_idx = cell
    candidates: list[Cell] = [
        (row_idx - 1, col_idx),
        (row_idx + 1, col_idx),
        (row_idx, col_idx - 1),
        (row_idx, col_idx + 1),
    ]
    reachable: list[tuple[Cell, int]] = []
    for next_row, next_col in candidates:
        if not (0 <= next_row < len(grid) and 0 <= next_col < len(grid[next_row])):
            continue
        tile = grid[next_row][next_col]
        if tile in TILE_ENTRY_COST:
            reachable.append(((next_row, next_col), TILE_ENTRY_COST[tile]))
    return reachable


def _reconstruct_path(came_from: dict[Cell, Cell | None], goal: Cell) -> list[Cell]:
    path: list[Cell] = []
    cursor: Cell | None = goal
    while cursor is not None:
        path.append(cursor)
        cursor = came_from[cursor]
    path.reverse()
    return path


def _relax_neighbors(
    grid: list[str],
    current: Cell,
    current_cost: int,
    best_cost: dict[Cell, int],
    came_from: dict[Cell, Cell | None],
    frontier: list[tuple[int, Cell]],
) -> None:
    for neighbor, step_cost in _neighbors_with_cost(grid, current):
        new_cost = current_cost + step_cost
        if new_cost < best_cost.get(neighbor, sys.maxsize):
            best_cost[neighbor] = new_cost
            came_from[neighbor] = current
            heapq.heappush(frontier, (new_cost, neighbor))


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = _locate_symbol(grid, "S")
    goal = _locate_symbol(grid, "G")
    if start is None or goal is None:
        return None

    frontier: list[tuple[int, Cell]] = [(0, start)]
    best_cost: dict[Cell, int] = {start: 0}
    came_from: dict[Cell, Cell | None] = {start: None}

    while frontier:
        current_cost, current = heapq.heappop(frontier)
        if current == goal:
            return _reconstruct_path(came_from, goal)
        if current_cost <= best_cost.get(current, sys.maxsize):
            _relax_neighbors(grid, current, current_cost, best_cost, came_from, frontier)

    return None


