import unittest

from pathfind import find_path


class VisibleTest(unittest.TestCase):
    def test_straight_corridor(self) -> None:
        self.assertEqual(find_path(["S..G"]), [(0, 0), (0, 1), (0, 2), (0, 3)])

    def test_prefers_cheaper_floor_detour_over_expensive_doors(self) -> None:
        grid = [
            "SDDG",
            "....",
        ]
        self.assertEqual(
            find_path(grid),
            [(0, 0), (1, 0), (1, 1), (1, 2), (1, 3), (0, 3)],
        )

    def test_takes_door_when_detour_is_costlier(self) -> None:
        grid = [
            "SDG#",
            ".#..",
            "....",
        ]
        self.assertEqual(find_path(grid), [(0, 0), (0, 1), (0, 2)])

    def test_returns_none_when_goal_unreachable(self) -> None:
        self.assertIsNone(find_path(["S#G"]))


if __name__ == "__main__":
    unittest.main()

